18	
19	import java.util.Locale;
20	import java.util.Map;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalizes an owner's postal address on create.
26	 *
27	 * <p>The raw value is trimmed, every run of whitespace is collapsed to a single space,
28	 * the text is upper-cased, and common street-type abbreviations are expanded to their
29	 * full words ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code ROAD},
30	 * {@code AVE}&rarr;{@code AVENUE}). This canonical form is what gets stored, returned,
31	 * and compared when detecting duplicate households.
32	 */
33	@Component
34	public class AddressNormalizer {
35	
36	    /** Whole-word abbreviations expanded to their canonical street type. */
37	    private static final Map<String, String> ABBREVIATIONS = Map.of(
38	        "ST", "STREET",
39	        "RD", "ROAD",
40	        "AVE", "AVENUE");
41	
42	    /**
43	     * Reduce {@code raw} to its canonical address form.
44	     *
45	     * @param raw the submitted address value (may be {@code null})
46	     * @return the normalized address, or an empty string when {@code raw} is {@code null}
47	     *         or blank
48	     */
49	    public String normalize(String raw) {
50	        if (raw == null) {
51	            return "";
52	        }
53	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
54	        if (collapsed.isEmpty()) {
55	            return "";
56	        }
57	        String[] tokens = collapsed.split(" ");
58	        StringBuilder normalized = new StringBuilder(collapsed.length());
59	        for (int i = 0; i < tokens.length; i++) {
60	            if (i > 0) {
61	                normalized.append(' ');
62	            }
63	            normalized.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
64	        }
65	        return normalized.toString();
66	    }
67	}
