19	import java.util.Map;
20	import java.util.regex.Pattern;
21	
22	import org.springframework.samples.petclinic.model.LocalityResolver;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Validates an owner's optional {@code postcode} against the region of their city.
27	 *
28	 * <p>A postcode is optional: when absent nothing is checked. When present it must be exactly four
29	 * digits and, for a city whose region is known (via {@link LocalityResolver}), must fall within
30	 * that region's inclusive range. A city with no known region accepts any four-digit postcode.
31	 */
32	@Component
33	public class PostcodeValidator {
34	
35	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
36	
37	    /** Region -> inclusive four-digit postcode range {@code {low, high}}. */
38	    private static final Map<String, int[]> REGION_RANGES = Map.of(
39	        "NSW", new int[] {2000, 2099},
40	        "VIC", new int[] {3000, 3099},
41	        "QLD", new int[] {4000, 4099});
42	
43	    /**
44	     * @param postcode the submitted postcode, or {@code null}/absent
45	     * @param city     the owner's city, used to resolve the applicable region
46	     * @throws InvalidPostcodeException if the postcode is present but not four digits, or is out of
47	     *                                  range for the city's region
48	     */
49	    public void validate(String postcode, String city) {
50	        if (postcode == null) {
51	            return;
52	        }
53	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
54	            throw new InvalidPostcodeException(postcode);
55	        }
56	        int[] range = REGION_RANGES.get(LocalityResolver.regionFor(city));
57	        if (range == null) {
58	            return;
59	        }
60	        int value = Integer.parseInt(postcode);
61	        if (value < range[0] || value > range[1]) {
62	            throw new InvalidPostcodeException(postcode);
63	        }
64	    }
65	}
